tool_input.command:
cd src/styles && python - <<'EOF'
import re
s=open('base.css',encoding='utf-8').read()
start=s.index(':root {'); end=s.index('}\n',start)+2
alias=''':root {
  /* Legacy names aliased onto hardlift tokens (src/styles/tokens.css) so nothing breaks mid-migration. */
  --color-bg: var(--color-surface-default);
  --color-surface: var(--color-surface-raised);
  --color-surface-muted: var(--color-surface-subtle);
  --color-sidebar-bg: var(--color-surface-default);
  --color-text: var(--color-text-primary);
  --color-text-muted: var(--color-text-secondary);
  --color-border: var(--color-border-default);
  --color-link: var(--color-text-secondary);
  --color-primary: var(--color-action-primary);
  --color-primary-text: var(--color-text-on-action);
  --color-focus: var(--color-focus-ring);
  --color-positive: var(--color-status-success);
  --color-negative: var(--color-status-danger);
  --color-backdrop: var(--color-scrim);
  --font-body: var(--font-family-body);
  --font-size-base: var(--font-size-md);
  --font-size-small: var(--font-size-sm);
  --font-size-h1: var(--font-size-3xl);
  --font-size-h2: var(--font-size-2xl);
  --line-height: var(--font-line-height-ui);
  --radius: var(--radius-sm);
  --radius-pill: var(--radius-full);
  --border-width: var(--border-width-thin);
  --space-1: var(--space-4);
  --space-2: var(--space-8);
  --space-3: var(--space-12);
  --space-6: var(--space-24);
}
'''
rest=s[end:]
# old --space-4 (16px) and --space-8 (32px) collide with token names; rename usages
rest=rest.replace('var(--space-4)','var(--space-16)').replace('var(--space-8)','var(--space-32)')
s=s[:start]+alias+rest
open('base.css','w',encoding='utf-8').write(s)
EOF
grep -n "var(--color-\(switch\|strength\|pill\|danger-bg\)\|--sidebar-width\|--content-max\|--avatar-size\|--switch-" base.css | head
